from fractions import Fraction as F
from sympy import factorint, primerange, totient
import math, cmath
def G(r):
    v=F(1)
    for p,a in factorint(r).items():
        if a>=3: return F(0)
        v*=F(-1,p*p-1)
    return v
def gq(q,l):  # without c: prod over p|q
    v=F(1,q)
    for p,t in factorint(q).items():
        v*=1/(1-F(1,p*p))
        if t>=2 and l%(p*p)==0: return F(0)
        if t==1 and l%p==0: v*=(1-F(1,p))
    return v
for q in range(1,60):
    lhs=q*sum(gq(q,l)**2 for l in range(1,q+1))
    rhs=sum(totient(r)*G(r)**2 for r in range(1,q+1) if q%r==0)
    assert lhs==rhs,(q)
print("moment ok")
# brute density check
N=10**6
sf=[1]*(N+1)
for m in range(2,int(N**.5)+1):
    for k in range(m*m,N+1,m*m): sf[k]=0
c=6/math.pi**2
for q in [4,8,9,12,18,25]:
    for l in range(q):
        cnt=sum(sf[n] for n in range(max(l,1) if l else q,N+1,q))
        print(q,l,round(cnt/N,5),round(c*float(gq(q,l)),5)) if l<3 else None
def ram(r,n): return sum(cmath.exp(2j*math.pi*a*n/r) for a in range(1,r+1) if math.gcd(a,r)==1).real
for n in [1,4,12,36]:
    s=sum(c*c*float(G(r))**2*ram(r,n) for r in range(1,3000) if G(r)!=0)
    S=1
    for p in primerange(2,10**6): S*=1-2/p**2
    for p in factorint(n):
        if n%(p*p)==0: S*=(p*p-1)/(p*p-2)
    print(n,s,S)
